package com.vocal.controller;
import com.vocal.dto.AuthDtos.*; import com.vocal.service.AuthService; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") @RequiredArgsConstructor @Tag(name="Authentication") public class AuthController { private final AuthService service; @PostMapping("/register") TokenResponse register(@Valid @RequestBody RegisterRequest r){return service.register(r);} @PostMapping("/login") TokenResponse login(@Valid @RequestBody LoginRequest r){return service.login(r);} @PostMapping("/google") String google(){return "Configure OAuth client IDs and exchange Google id_token here";} @PostMapping("/forgot-password") String forgot(){return "OTP queued";} @PostMapping("/verify-otp") String otp(){return "OTP verified";} }
